#!/usr/bin/env python3
"""
Passo 6 - Barra de busca holo (Player3D / Galeria3D).

Aplica de uma vez, em 6 arquivos Java + 1 layout XML novo, a
implementacao completa da barra de busca fixa no topo, que filtra
in-memory (sem nova query ao MediaStore) as listas de Albuns, Artistas,
Playlists, Ultimos Reproduzidos e Musicas.

Rode este script de dentro de ~/Galeria3D (raiz do repo clonado).
Idempotente: pode rodar 2x sem quebrar nada.
Cada arquivo tocado ganha um .bak antes de ser sobrescrito.
"""

import base64
import io
import os
import shutil
import sys
import tarfile

# Caminho -> conteudo final esperado (relativo a raiz do repo).
FILES = {
    "app/src/main/java/com/android/gallery3d/app/GalleryActivity.java": "GalleryActivity.java",
    "app/src/main/java/com/android/gallery3d/app/ActivityState.java": "ActivityState.java",
    "app/src/main/java/com/android/gallery3d/app/AlbumPage.java": "AlbumPage.java",
    "app/src/main/java/com/android/gallery3d/app/AlbumSetPage.java": "AlbumSetPage.java",
    "app/src/main/java/com/android/gallery3d/data/ClusterAlbum.java": "ClusterAlbum.java",
    "app/src/main/java/com/android/gallery3d/data/ClusterAlbumSet.java": "ClusterAlbumSet.java",
    "app/src/main/res/layout/search_bar_holo.xml": "search_bar_holo.xml",
}

MARKER = "Passo 6"

PAYLOAD_B64 = ""


def load_payload():
    raw = base64.b64decode(PAYLOAD_B64)
    return tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz")


def already_applied():
    ga_path = "app/src/main/java/com/android/gallery3d/app/GalleryActivity.java"
    if not os.path.isfile(ga_path):
        return False
    with open(ga_path, "r", encoding="utf-8") as f:
        return "setupSearchBar" in f.read()


def main():
    if not os.path.isdir("app/src/main/java/com/android/gallery3d"):
        print("ERRO: nao encontrei app/src/main/java/com/android/gallery3d")
        print("Rode este script de dentro da pasta raiz do repo (~/Galeria3D).")
        sys.exit(1)

    if already_applied():
        print("Passo 6 ja aplicado anteriormente (GalleryActivity.java ja tem")
        print("setupSearchBar) — nada a fazer (script e idempotente).")
        sys.exit(0)

    tar = load_payload()
    members = {m.name.lstrip("./"): m for m in tar.getmembers()}

    # Confere que o payload tem todos os arquivos esperados antes de tocar
    # em qualquer coisa no disco.
    for repo_path, payload_name in FILES.items():
        if payload_name not in members:
            print(f"ERRO interno: payload nao contem {payload_name}")
            sys.exit(1)

    backups = []
    try:
        for repo_path, payload_name in FILES.items():
            new_content = tar.extractfile(members[payload_name]).read()

            if os.path.isfile(repo_path):
                backup_path = repo_path + ".bak"
                shutil.copyfile(repo_path, backup_path)
                backups.append(backup_path)
                print(f"Backup criado: {backup_path}")
            else:
                os.makedirs(os.path.dirname(repo_path), exist_ok=True)

            with open(repo_path, "wb") as f:
                f.write(new_content)
            print(f"Atualizado: {repo_path}")

    except Exception as e:
        print(f"ERRO durante a aplicacao: {e}")
        print("Arquivos ja copiados tem backup .bak ao lado, revise manualmente se necessario.")
        sys.exit(1)

    print()
    print("Passo 6 aplicado com sucesso.")
    print()
    print("O que foi feito:")
    print("- Novo layout res/layout/search_bar_holo.xml (EditText + icone de")
    print("  lupa, reaproveitando o tema Holo do app, sem shape/9-patch novos)")
    print("- GalleryActivity: infla a barra dentro do FrameLayout 'header' ja")
    print("  existente em main.xml (antes sempre gone, sem uso); liga um")
    print("  TextWatcher que repassa o texto digitado ao estado ativo")
    print("- ActivityState: novo metodo onSearchQueryChanged(query), vazio por")
    print("  padrao (nao afeta PhotoPage/SlideshowPage/etc)")
    print("- AlbumSetPage e AlbumPage: sobrescrevem esse metodo e filtram o")
    print("  MediaSet ativo em memoria (ClusterAlbumSet / ClusterAlbum)")
    print("- ClusterAlbum e ClusterAlbumSet: guardam a lista completa e uma")
    print("  lista filtrada; filtro por TITLE/artista (faixas) e por nome do")
    print("  card (albuns/artistas/playlists); sem nova consulta ao MediaStore")
    print()
    print("Proximo passo: recompile o app e teste digitar na barra do topo")
    print("em cada um dos 5 filtros do spinner (Albuns/Artistas/Playlists/")
    print("Ultimos Reproduzidos/Musicas).")


if __name__ == "__main__":
    main()
